//! Grades this port against a table generated by `gobwas/glob` v0.2.3 itself.
//!
//! The table is the oracle, not the library's documentation: the two disagree
//! about separators, and it is the table that decides which files `rtk fmt`
//! touches. `testdata/generate/` holds the pinned generator. This test runs it
//! at runtime and compares its stdout directly; no large answer file is saved.
//! Go is required, and unavailable or failed generation is a test failure.

use std::{path::PathBuf, process::Command};

use rtk_gobwas_glob::Glob;
use serde::Deserialize;

#[derive(Debug, Deserialize)]
struct Case {
	pattern: String,
	/// The separators passed to `glob.Compile`, as a string of characters.
	/// Absent means none, which is how `tk` compiles every `--exclude`.
	#[serde(default)]
	separators: String,
	/// `glob.Compile`'s message when it rejected the pattern.
	#[serde(default)]
	error: String,
	#[serde(default)]
	matches: Vec<String>,
	#[serde(default)]
	rejects: Vec<String>,
	#[serde(default)]
	matches_hex: Vec<String>,
	#[serde(default)]
	rejects_hex: Vec<String>,
}

impl Case {
	fn generate() -> Vec<Self> {
		let generator = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("testdata/generate");
		let output = Command::new("go")
			.args(["run", "-mod=readonly", "."])
			.env("GOFLAGS", "-buildvcs=false")
			.current_dir(generator)
			.output()
			.expect("glob parity requires Go; the generator must run");
		assert!(
			output.status.success(),
			"Go truth-table generation failed ({}):\n{}",
			output.status,
			String::from_utf8_lossy(&output.stderr)
		);
		let cases: Vec<Self> =
			serde_json::from_slice(&output.stdout).expect("generated truth table is valid JSON");
		assert!(!cases.is_empty(), "generated truth table is empty");
		cases
	}
}

#[test]
fn matches_the_generated_truth_table() {
	let cases = Case::generate();

	let mut failures: Vec<String> = Vec::new();

	for case in &cases {
		let separators: Vec<char> = case.separators.chars().collect();
		let label = if separators.is_empty() {
			format!("{:?}", case.pattern)
		} else {
			format!("{:?} sep {:?}", case.pattern, case.separators)
		};

		let compiled = Glob::with_separators(&case.pattern, &separators);

		if !case.error.is_empty() {
			match compiled {
				Ok(_) => failures.push(format!(
					"{label}: gobwas rejected it with {:?}, this port accepted it",
					case.error
				)),
				Err(err) if err.message() != case.error => failures.push(format!(
					"{label}: gobwas said {:?}, this port said {:?}",
					case.error,
					err.message()
				)),
				Err(_) => {}
			}
			continue;
		}

		let glob = match compiled {
			Ok(glob) => glob,
			Err(err) => {
				failures.push(format!(
					"{label}: gobwas accepted it, this port rejected it with {:?}",
					err.message()
				));
				continue;
			}
		};

		for (subjects, expected) in [(&case.matches_hex, true), (&case.rejects_hex, false)] {
			for subject in subjects {
				let bytes: Vec<u8> = (0..subject.len())
					.step_by(2)
					.map(|i| {
						u8::from_str_radix(&subject[i..i + 2], 16).expect("hex filename bytes")
					})
					.collect();
				if glob.is_match_bytes(&bytes) != expected {
					failures.push(format!("{label}: bytes {subject} should match: {expected}"));
				}
			}
		}

		for subject in &case.matches {
			if !glob.is_match(subject) {
				failures.push(format!("{label}: should match {subject:?}, did not"));
			}
		}
		for subject in &case.rejects {
			if glob.is_match(subject) {
				failures.push(format!("{label}: should not match {subject:?}, did"));
			}
		}
	}

	assert!(
		failures.is_empty(),
		"{} of {} cases diverge from gobwas/glob:\n{}",
		failures.len(),
		cases.len(),
		failures.join("\n")
	);
}
